import os
import re
import time
import hashlib
import hmac
from flask import Flask, request, jsonify, make_response
from functools import wraps
import threading

app = Flask(__name__)

# Rate limiting state
rate_limit_lock = threading.Lock()
request_counts = {}
RATES_WINDOW = 60
MAX_REQUESTS = 30

# Retry configuration
MAX_RETRIES = 3
RETRY_DELAY = 0.5

API_SECRET = os.environ.get('API_SECRET')
if not API_SECRET:
    raise RuntimeError(
        'API_SECRET environment variable must be set; refusing to start with an insecure default.'
    )

def verify_hmac(payload, signature):
    expected = hmac.new(API_SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

def rate_limit(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        client_ip = request.remote_addr
        current_time = time.time()
        with rate_limit_lock:
            if client_ip not in request_counts:
                request_counts[client_ip] = []
            request_counts[client_ip] = [
                t for t in request_counts[client_ip]
                if current_time - t < RATES_WINDOW
            ]
            if len(request_counts[client_ip]) >= MAX_REQUESTS:
                return jsonify({'error': 'Rate limit exceeded'}), 429
            request_counts[client_ip].append(current_time)
        return f(*args, **kwargs)
    return decorated

class SolidityProcessor:
    """Processes Solidity files and generates compilation metadata headers."""

    ALLOWED_PRAGMAS = ['solidity', 'experimental']
    MAX_FILE_SIZE = 1024 * 1024  # 1MB

    def __init__(self):
        self.compile_cache = {}
        self._lock = threading.Lock()

    def _extract_pragma(self, source_code):
        """Extract pragma version from Solidity source."""
        match = re.search(r'pragma\s+(\w+)\s+([^;]+);', source_code)
        if match:
            pragma_type = match.group(1)
            pragma_value = match.group(2).strip()
            if pragma_type in self.ALLOWED_PRAGMAS:
                return pragma_type, pragma_value
        return None, None

    def _extract_contract_name(self, source_code):
        """Extract the primary contract name."""
        match = re.search(r'contract\s+(\w+)', source_code)
        if match:
            return match.group(1)
        return 'Unknown'

    def _sanitize_metadata_value(self, value):
        """Sanitize values for use in HTTP response headers.
        Removes characters that could cause header injection."""
        # Remove null bytes
        sanitized = value.replace('\x00', '')
        # Remove CR and LF characters to prevent CRLF injection
        sanitized = sanitized.replace('\r', '').replace('\n', '')
        # Collapse whitespace sequences to single space
        sanitized = re.sub(r'[\t ]+', ' ', sanitized)
        return sanitized.strip()

    def _build_compilation_report(self, contract_name, pragma_type, pragma_value, file_hash):
        """Build a compilation status report string."""
        report_lines = []
        report_lines.append(f"Contract: {contract_name}")
        report_lines.append(f"Pragma: {pragma_type} {pragma_value}")
        report_lines.append(f"Hash: {file_hash}")
        report_lines.append(f"Status: queued")
        return '\n'.join(report_lines)

    def process_file(self, filename, source_code, retry_count=0):
        """Process a Solidity file with retry logic."""
        if len(source_code) > self.MAX_FILE_SIZE:
            return None, 'File too large'

        try:
            file_hash = hashlib.sha256(source_code.encode()).hexdigest()[:16]

            with self._lock:
                if file_hash in self.compile_cache:
                    return self.compile_cache[file_hash], None

            pragma_type, pragma_value = self._extract_pragma(source_code)
            contract_name = self._extract_contract_name(source_code)

            if not pragma_type:
                if retry_count < MAX_RETRIES:
                    time.sleep(RETRY_DELAY)
                    return self.process_file(filename, source_code, retry_count + 1)
                return None, 'No valid pragma found'

            report = self._build_compilation_report(
                contract_name, pragma_type, pragma_value, file_hash
            )

            result = {
                'filename': filename,
                'contract_name': contract_name,
                'pragma': f"{pragma_type} {pragma_value}",
                'file_hash': file_hash,
                'report': report
            }

            with self._lock:
                self.compile_cache[file_hash] = result

            return result, None

        except Exception as e:
            if retry_count < MAX_RETRIES:
                time.sleep(RETRY_DELAY)
                return self.process_file(filename, source_code, retry_count + 1)
            return None, str(e)

processor = SolidityProcessor()

@app.route('/api/v1/compile', methods=['POST'])
@rate_limit
def compile_solidity():
    """Endpoint to submit Solidity files for compilation."""
    if not request.is_json:
        return jsonify({'error': 'Content-Type must be application/json'}), 400

    data = request.get_json()
    filename = data.get('filename', '')
    source_code = data.get('source', '')

    if not filename or not source_code:
        return jsonify({'error': 'Missing filename or source'}), 400

    if not filename.endswith('.sol'):
        return jsonify({'error': 'File must have .sol extension'}), 400

    # Validate filename doesn't contain path traversal
    if '..' in filename or '/' in filename or '\\' in filename:
        return jsonify({'error': 'Invalid filename'}), 400

    result, error = processor.process_file(filename, source_code)

    if error:
        return jsonify({'error': error}), 422

    # Build response with compilation metadata in headers
    response = make_response(jsonify({
        'status': 'success',
        'data': result
    }))

    # Set custom headers with compilation info
    sanitized_name = processor._sanitize_metadata_value(result['contract_name'])
    sanitized_pragma = processor._sanitize_metadata_value(result['pragma'])

    response.headers['X-Contract-Name'] = sanitized_name
    response.headers['X-Pragma-Version'] = sanitized_pragma
    response.headers['X-File-Hash'] = result['file_hash']
    response.headers['X-Compilation-Status'] = 'queued'

    return response

@app.route('/api/v1/status/<file_hash>', methods=['GET'])
@rate_limit
def get_status(file_hash):
    """Check compilation status by file hash."""
    if not re.match(r'^[a-f0-9]{16}$', file_hash):
        return jsonify({'error': 'Invalid hash format'}), 400

    with processor._lock:
        if file_hash in processor.compile_cache:
            return jsonify({'status': 'found', 'data': processor.compile_cache[file_hash]})

    return jsonify({'status': 'not_found'}), 404

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080, debug=False)
